use std::collections::BTreeMap;
use std::path::Path;

use callisto_model::{
    select_last_tag, CommandRunner, CommitSha, Diagnostic, LastTag, LastTagSelection, PackageId, TagTemplate,
    VersionGrammar,
};
use callisto_vcs::{GitAccess, GitDataSource};

use crate::config::ResolvedConfig;
use crate::error::GraphError;
use crate::resolver::DependencyResolver;

/// Fetches the full, unfiltered list of every tag name in the repository at
/// `root`, via [`GitAccess`] (native gix, falling back to a `CommandRunner`-
/// shelled `git tag --list` when gix is unavailable -- most notably on
/// `wasm32`).
///
/// Deliberately fetches with no glob pattern: callers filter afterwards
/// via [`matching_tags`], using the same `globset` matcher both
/// `GitDataSource` backends use internally -- identical tag-selection
/// semantics regardless of backend, and lets the fetch batch once across
/// every package (see [`TagIndex::build`]) instead of once per package,
/// important on `wasm32` where each `CommandRunner` call is a full Extism
/// round-trip.
fn fetch_all_tags(git: &GitAccess<'_>) -> Result<Vec<String>, GraphError> {
    let tags = git.list_tags(None)?;
    Ok(tags.into_iter().map(|t| t.0).collect())
}

/// Filters `all_tags` down to those matching `template`'s glob.
///
/// Uses the same `globset::Glob` matching
/// `callisto_vcs::GitRepository::list_tags` applies internally, kept in
/// sync so tag selection is byte-identical whether `all_tags` came from
/// gix or the `CommandRunner` fallback in [`fetch_all_tags`]. Includes
/// error behavior: a `template.glob()` that fails to compile surfaces as
/// `Err(GraphError::Vcs(VcsError::InvalidGlob))` -- matching every tag is
/// the unsafe alternative, since a malformed template must never silently
/// make "last tag" resolution pick an unrelated package's tag.
fn matching_tags<'a>(all_tags: &'a [String], template: &TagTemplate) -> Result<Vec<&'a str>, GraphError> {
    let glob = template.glob();
    let matcher = globset::Glob::new(&glob).map(|g| g.compile_matcher()).map_err(|e| {
        GraphError::Vcs(callisto_vcs::VcsError::InvalidGlob {
            pattern: glob.clone(),
            message: e.to_string(),
        })
    })?;

    Ok(all_tags
        .iter()
        .filter(|t| matcher.is_match(t.as_str()))
        .map(|s| s.as_str())
        .collect())
}

/// Selects the highest-versioned tag matching `template` out of a full tag
/// list previously obtained via [`fetch_all_tags`].
fn select_from_tags(
    all_tags: &[String],
    template: &TagTemplate,
    grammar: VersionGrammar,
) -> Result<LastTagSelection, GraphError> {
    let candidates = matching_tags(all_tags, template)?;
    select_last_tag(template, grammar, candidates).map_err(GraphError::from)
}

/// Resolves the last release tag matching a single package's `template`.
///
/// Kept for API compatibility with existing callers, and safe to use
/// standalone. Note that this re-fetches the full tag list (gix discovery
/// or a `CommandRunner` round-trip) on every call; callers resolving tags
/// for many packages at once -- notably [`TagIndex::build`] -- fetch the
/// list once and reuse it across packages rather than calling this
/// function in a loop.
pub fn last_tag_for<R: CommandRunner>(
    runner: &R,
    root: &Path,
    template: &TagTemplate,
    grammar: VersionGrammar,
) -> Result<LastTagSelection, GraphError> {
    let git = GitAccess::discover(root, runner);
    let all_tags = fetch_all_tags(&git)?;
    select_from_tags(&all_tags, template, grammar)
}

pub struct TagIndex {
    last: BTreeMap<PackageId, Option<LastTag>>,
    templates: BTreeMap<PackageId, TagTemplate>,
    pre_cursor: BTreeMap<PackageId, Option<CommitSha>>,
    /// The full, unfiltered raw tag list fetched once during `build` (see
    /// `fetch_all_tags`), kept around so callers checking whether a specific
    /// tag name already exists (e.g. `create_tags_with_options`, once per
    /// release) can consult this in-memory set instead of re-querying `git`
    /// once per check.
    all_tags: std::collections::BTreeSet<String>,
    pub diagnostics: Vec<Diagnostic>,
}

impl TagIndex {
    pub fn build<D: DependencyResolver>(
        git: &GitAccess<'_>,
        graph: &D,
        _cfg: &ResolvedConfig,
    ) -> Result<Self, GraphError> {
        let mut last = BTreeMap::new();
        let mut templates = BTreeMap::new();
        let mut pre_cursor = BTreeMap::new();
        let diagnostics = Vec::new();

        // Fetch the raw tag list exactly once for the whole build, not once
        // per package -- see `fetch_all_tags` for why (avoids N gix
        // discoveries / N host round-trips for N packages). `git` is shared
        // with the caller rather than discovered fresh here, so a single
        // `Workspace`-scoped command that also needs git for other reasons
        // (e.g. `plan_publish`'s head_sha resolution) doesn't pay for a
        // second discovery.
        let all_tags = fetch_all_tags(git)?;
        let all_tags_set: std::collections::BTreeSet<String> = all_tags.iter().cloned().collect();

        for pkg in graph.packages() {
            let default_tmpl = TagTemplate::parse(&format!("{}@{{version}}", pkg.id.display_name()))?;
            let tmpl = pkg.tag_template.clone().unwrap_or(default_tmpl);
            let sel = select_from_tags(&all_tags, &tmpl, pkg.version_grammar()?)?;
            last.insert(pkg.id.clone(), sel.chosen);
            templates.insert(pkg.id.clone(), tmpl);
            pre_cursor.insert(pkg.id.clone(), None);
        }

        Ok(TagIndex {
            last,
            templates,
            pre_cursor,
            all_tags: all_tags_set,
            diagnostics,
        })
    }

    pub fn last_tag(&self, id: &PackageId) -> Option<&LastTag> {
        self.last.get(id).and_then(|opt| opt.as_ref())
    }

    pub fn template(&self, id: &PackageId) -> &TagTemplate {
        &self.templates[id]
    }

    pub fn pre_cursor(&self, id: &PackageId) -> Option<&CommitSha> {
        self.pre_cursor.get(id).and_then(|opt| opt.as_ref())
    }

    /// Returns whether `tag_name` is present in the raw tag list fetched
    /// during `build` -- an exact match, not a glob. Lets callers checking
    /// tag existence once per release (e.g. `create_tags_with_options`)
    /// consult this in-memory set instead of shelling out to `git` again
    /// for each one.
    pub fn contains_tag(&self, tag_name: &str) -> bool {
        self.all_tags.contains(tag_name)
    }

    /// Constructs an empty `TagIndex` with no packages or tags — useful in
    /// unit tests that do not exercise tag-based logic.
    pub fn empty() -> Self {
        TagIndex {
            last: BTreeMap::new(),
            templates: BTreeMap::new(),
            pre_cursor: BTreeMap::new(),
            all_tags: std::collections::BTreeSet::new(),
            diagnostics: Vec::new(),
        }
    }
}

