    let mut pre_cursor = BTreeMap::new();
    let diagnostics = Vec::new();

    // Fetch the raw tag list exactly once for the whole build, not once
    // per package -- see `fetch_all_tags` for why (avoids N gix
    // discoveries / N host round-trips for N packages). `git` is shared
    // with the caller rather than discovered fresh here, so a single
    // `Workspace`-scoped command that also needs git for other reasons
    // (e.g. `plan_publish`'s head_sha resolution) doesn't pay for a
    // second discovery.
    let all_tags = fetch_all_tags(git)?;
    let all_tags_set: std::collections::BTreeSet<String> = all_tags.iter().cloned().collect();

    for pkg in graph.packages() {
        let default_tmpl = TagTemplate::parse(&format!("{}@{{version}}", pkg.id.display_name()))?;
        let tmpl = pkg.tag_template.clone().unwrap_or(default_tmpl);
        let sel = select_from_tags(&all_tags, &tmpl, pkg.version_grammar()?)?;
        last.insert(pkg.id.clone(), sel.chosen);
        templates.insert(pkg.id.clone(), tmpl);
        pre_cursor.insert(pkg.id.clone(), None);
    }

    Ok(TagIndex {
        last,
        templates,
        pre_cursor,
        all_tags: all_tags_set,
        diagnostics,
    })
}

