153	/// by [turning commit-graph support off][Platform::use_commit_graph()]. This certainly is a micro-optimization though.
154	pub struct Platform<'repo> {
155	    /// The owning repository.
156	    pub repo: &'repo Repository,
157	    pub(crate) tips: Vec<ObjectId>,
158	    pub(crate) hidden: Vec<ObjectId>,
