1	//! Git-backed test doubles and repo-setup helpers shared across crates'
2	//! test suites.
3	
4	use std::path::Path;
5	
6	use callisto_model::{CommandError, CommandOutput, CommandRunner};
7	
8	/// A [`CommandRunner`] double that errors on every invocation.
9	///
10	/// Used to prove that a code path resolves git state without shelling out
11	/// through `CommandRunner` at all (e.g. via `callisto_vcs::GitRepository`/gix
12	/// instead) -- a runner that always fails must not affect the result.
13	pub struct PoisonedRunner;
14	
15	impl CommandRunner for PoisonedRunner {
16	    fn run(&self, program: &str, _args: &[&str], _cwd: &Path) -> Result<CommandOutput, CommandError> {
17	        Err(CommandError::Io {
18	            program: program.to_string(),
19	            message: "poisoned runner: this code path must not shell out to git".to_string(),
20	        })
21	    }
22	}
23	
24	/// Runs `git` with `args` in `dir`, panicking if `git` is unavailable or the
25	/// invocation fails. Test-only helper for building fixture repos.
26	pub fn run_git(dir: &Path, args: &[&str]) {
27	    let status = std::process::Command::new("git")
28	        .args(args)
29	        .current_dir(dir)
30	        .status()
31	        .expect("git must be installed to run this test");
32	    assert!(status.success(), "git {args:?} failed in {dir:?}");
33	}
34	
35	/// Initializes `root` as a git repo with a fixed test identity
36	/// (`test@example.com` / `Test`), suitable for building fixture repos across
37	/// test suites.
38	pub fn init_repo(root: &Path) {
39	    run_git(root, &["init", "-q"]);
40	    run_git(root, &["config", "user.email", "test@example.com"]);
41	    run_git(root, &["config", "user.name", "Test"]);
42	}

