//! Black-box protocol verification for the callisto moon extension.
//!
//! Unlike the type-level `cargo check --target wasm32-wasip1 --features pdk`
//! gate, this drives the *compiled* `callisto-moon.wasm` module through a
//! real wasmtime-backed Extism plugin container (via `moon_pdk_test_utils` /
//! `warpgate`), exercising the actual `register_extension` and
//! `execute_extension` wire calls moon itself would make.
//!
//! `moon_pdk_test_utils::find_wasm_file()` looks for a file literally named
//! `{CARGO_PKG_NAME}.wasm` (i.e. `callisto-moon.wasm`, hyphenated), but
//! cargo's own wasm32 cdylib output is `callisto_moon.wasm` (underscored).
//! `resolve_wasm_file` below builds the module (if needed) and stages a
//! correctly-named copy under `WARPGATE_PLUGINS_DIR` so discovery succeeds.

use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;
use std::sync::Once;

use moon_pdk_test_utils::{create_empty_moon_sandbox, ExecuteExtensionInput, RegisterExtensionInput};

static BUILD_WASM: Once = Once::new();

fn workspace_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .ancestors()
        .nth(2)
        .expect("callisto-moon manifest dir has no workspace-root ancestor")
        .to_path_buf()
}

/// Ensures `callisto-moon.wasm` (hyphenated, as `find_wasm_file()` expects)
/// exists in a directory pointed to by `WARPGATE_PLUGINS_DIR`, building the
/// real wasm32-wasip1 cdylib artifact first if it isn't already present.
fn resolve_wasm_file() {
    if BUILD_WASM.is_completed() {
        return;
    }
    BUILD_WASM.call_once_force(|_| {
        let root = workspace_root();
        let built = root.join("target/wasm32-wasip1/debug/callisto_moon.wasm");

        let is_valid = built.exists() && built.metadata().map(|m| m.len() > 100).unwrap_or(false);
        if !is_valid {
            // `--crate-type cdylib` is passed explicitly here rather than
            // declared in Cargo.toml's [lib] section: a manifest-level
            // cdylib crate-type would make cargo also attempt (and fail) a
            // native cdylib build whenever the "pdk" feature is enabled
            // natively (e.g. `cargo llvm-cov --all-features`), since pdk's
            // code references extism-pdk's WASM-host-only import symbols.
            let status = Command::new("cargo")
                .env_remove("RUSTFLAGS")
                .env_remove("CARGO_ENCODED_RUSTFLAGS")
                .env_remove("CARGO_LLVM_COV")
                .env_remove("CARGO_LLVM_COV_FLAGS")

//! Manifest reading and MatrixReport assembly for `callisto matrix`.
//! Private helpers only -- the public entry point is
//! `crate::commands::matrix::matrix`.

/// Per-triple CI scheduling attributes for the 18 triples
/// `crate::napi::triple_to_role` recognises today. This table is NEW code:
/// `triple_to_role`'s `ManifestRole::Platform` carries only platform/arch/abi
/// and has no concept of hostRunner/useCross, so this cannot be derived from
/// it. Returns `None` for any triple `triple_to_role` does not recognise --
/// callers must treat that as the AC-011 diagnostic path, never a silent
/// default.
pub(crate) fn triple_host_runner_use_cross(triple: &str) -> Option<(&'static str, bool)> {
    Some(match triple {
        "aarch64-apple-darwin" => ("macos-latest", false),
        "x86_64-apple-darwin" => ("macos-13", false),
        "x86_64-unknown-linux-gnu" => ("ubuntu-latest", false),
        "x86_64-unknown-linux-musl" => ("ubuntu-latest", true),
        "aarch64-unknown-linux-gnu" => ("ubuntu-latest", true),
        "aarch64-unknown-linux-musl" => ("ubuntu-latest", true),
        "x86_64-pc-windows-msvc" => ("windows-latest", false),
        "i686-pc-windows-msvc" => ("windows-latest", false),
        "aarch64-pc-windows-msvc" => ("windows-latest", false),
        "armv7-unknown-linux-gnueabihf" => ("ubuntu-latest", true),
        "x86_64-unknown-freebsd" => ("ubuntu-latest", true),
        "aarch64-linux-android" => ("ubuntu-latest", true),
        "armv7-linux-androideabi" => ("ubuntu-latest", true),
        "riscv64gc-unknown-linux-gnu" => ("ubuntu-latest", true),
        "powerpc64le-unknown-linux-gnu" => ("ubuntu-latest", true),
        "s390x-unknown-linux-gnu" => ("ubuntu-latest", true),
        "wasm32-wasip1" => ("ubuntu-latest", false),
        "wasm32-unknown-unknown" => ("ubuntu-latest", false),
        _ => return None,
    })
}

/// AC-013: artifactName is always the literal "native-" concatenated with
/// the triple string, for every recognised triple.
pub(crate) fn artifact_name_for_triple(triple: &str) -> String {
    format!("native-{triple}")
}

use std::path::Path;

use callisto_model::{ManifestError, ManifestFormat, ManifestRole, PlatformTarget};

