fn artifact_name_is_native_prefixed_triple() {
    assert_eq!(
        artifact_name_for_triple("aarch64-apple-darwin"),
        "native-aarch64-apple-darwin"
    );
    assert_eq!(
        artifact_name_for_triple("x86_64-unknown-linux-musl"),
        "native-x86_64-unknown-linux-musl"
    );
}

